1	import java.util.Arrays;
2	import java.util.Comparator;
3	import java.util.NoSuchElementException;
4	
5	class MinHeapTest {
6	
7	    interface ThrowingRunnable {
8	        void run() throws Exception;
9	    }
10	
11	    private static int passed = 0;
12	    private static int failed = 0;
13	
14	    public static void main(String[] args) {
15	        testInsertAndExtract();
16	        testRemoveAt();
17	        testDecreaseKey();
18	        testIncreaseKey();
19	        testChangeKey();
20	        testAutoResize();
21	        testEmptyHeap();
22	        testFromArray();
23	        testWithStrings();
24	        testMaxHeap();
25	        testCustomComparator();
26	        testToString();
27	        testToArray();
28	        testToSortedArray();
29	        testSort();
30	        testAddAll();
31	        testContains();
32	        testRemove();
33	        testClear();
34	        testIterable();
35	        testEmptyArray();
36	        testIndexBoundsChecking();
37	        testOriginalScenario();
38	
39	        System.out.println("\n" + passed + " passed, " + failed + " failed.");
40	        if (failed > 0) System.exit(1);
41	    }
42	
43	    private static void assertEqual(Object expected, Object actual, String msg) {
44	        if (expected.equals(actual)) {
45	            System.out.println("PASS: " + msg);
46	            passed++;
47	        } else {
48	            System.out.println("FAIL: " + msg + " (expected=" + expected + ", got=" + actual + ")");
49	            failed++;
50	        }
51	    }
52	
53	    private static void assertTrue(boolean condition, String msg) {
54	        if (condition) {
55	            System.out.println("PASS: " + msg);
56	            passed++;
57	        } else {
58	            System.out.println("FAIL: " + msg);
59	            failed++;
60	        }
61	    }
62	
63	    private static void assertThrows(ThrowingRunnable r, Class<? extends Exception> exClass, String msg) {
64	        try {
65	            r.run();
66	            System.out.println("FAIL: " + msg + " (no exception thrown)");
67	            failed++;
68	        } catch (Exception e) {
69	            if (exClass.isInstance(e)) {
70	                System.out.println("PASS: " + msg);
71	                passed++;
72	            } else {
73	                System.out.println("FAIL: " + msg + " (wrong exception: " + e.getClass().getSimpleName() + ")");
74	                failed++;
75	            }
76	        }
77	    }
78	
79	    private static void testInsertAndExtract() {
80	        MinHeap<Integer> h = MinHeap.naturalOrder();
81	        h.insert(5);
82	        h.insert(3);
83	        h.insert(8);
84	        h.insert(1);
85	        assertEqual(1, h.extractMin(), "extractMin returns smallest");
86	        assertEqual(3, h.extractMin(), "extractMin returns next smallest");
87	        assertEqual(5, h.extractMin(), "extractMin returns next");
88	        assertEqual(8, h.extractMin(), "extractMin returns last");
89	        assertTrue(h.isEmpty(), "heap is empty after all extractions");
90	    }
91	
92	    private static void testRemoveAt() {
93	        MinHeap<Integer> h = MinHeap.naturalOrder(11);
94	        h.insert(3);
95	        h.insert(2);
96	        h.removeAt(1);
97	        h.insert(15);
98	        h.insert(5);
99	        h.insert(4);
100	        h.insert(45);
101	        assertEqual(2, h.extractMin(), "extractMin after removeAt");
102	        assertEqual(4, h.getMin(), "getMin after extract");
103	
104	        MinHeap<Integer> h2 = MinHeap.naturalOrder();
105	        h2.insert(1);
106	        h2.insert(3);
107	        h2.insert(5);
108	        h2.removeAt(2);
109	        assertEqual(2, h2.size(), "size after removing last element");
110	        assertEqual(1, h2.extractMin(), "min unchanged after removing last");
111	
112	        MinHeap<Integer> h3 = MinHeap.naturalOrder();
113	        h3.insert(1);
114	        h3.insert(3);
115	        h3.insert(5);
116	        h3.removeAt(0);
117	        assertEqual(3, h3.extractMin(), "new root after removing old root");
118	    }
119	
120	    private static void testDecreaseKey() {
121	        MinHeap<Integer> h = MinHeap.naturalOrder();
122	        h.insert(10);
123	        h.insert(20);
124	        h.insert(30);
125	        h.decreaseKey(2, 5);
126	        assertEqual(5, h.extractMin(), "decreaseKey moves element up correctly");
127	    }
128	
129	    private static void testIncreaseKey() {
130	        MinHeap<Integer> h = MinHeap.naturalOrder();
131	        h.insert(1);
132	        h.insert(5);
133	        h.insert(10);
134	        h.increaseKey(0, 15);
135	        assertEqual(5, h.extractMin(), "increaseKey on root restores heap property");
136	    }
137	
138	    private static void testChangeKey() {
139	        MinHeap<Integer> h = MinHeap.naturalOrder();
140	        h.insert(5);
141	        h.insert(10);
142	        h.changeKey(1, 1);
143	        assertEqual(1, h.extractMin(), "changeKey decrease works");
144	
145	        MinHeap<Integer> h2 = MinHeap.naturalOrder();
146	        h2.insert(3);
147	        h2.insert(8);
148	        h2.changeKey(0, 20);
149	        assertEqual(8, h2.extractMin(), "changeKey increase works");
150	
151	        MinHeap<Integer> h3 = MinHeap.naturalOrder();
152	        h3.insert(7);
153	        h3.changeKey(0, 7);
154	        assertEqual(7, h3.getMin(), "changeKey no-op when value unchanged");
155	    }
156	
157	    private static void testAutoResize() {
158	        MinHeap<Integer> h = MinHeap.naturalOrder(2);
159	        for (int i = 10; i >= 1; i--) {
160	            h.insert(i);
161	        }
162	        assertEqual(10, h.size(), "auto-resize: correct size after growing beyond initial capacity");
163	        assertEqual(1, h.extractMin(), "auto-resize: extracts minimum correctly");
164	        assertEqual(2, h.extractMin(), "auto-resize: maintains order after resize");
165	    }
166	
167	    private static void testEmptyHeap() {
168	        MinHeap<Integer> h = MinHeap.naturalOrder();
169	        assertTrue(h.isEmpty(), "new heap is empty");
170	        assertEqual(0, h.size(), "new heap has size 0");
171	        assertThrows(() -> h.extractMin(), NoSuchElementException.class, "extractMin on empty throws");
172	        assertThrows(() -> h.getMin(), NoSuchElementException.class, "getMin on empty throws");
173	    }
174	
175	    private static void testFromArray() {
176	        Integer[] arr = {5, 3, 8, 1, 9, 2};
177	
178	        MinHeap<Integer> h = MinHeap.from(arr);
179	        assertEqual(6, h.size(), "from: correct size");
180	        assertEqual(1, h.extractMin(), "from: extracts minimum");
181	        assertEqual(2, h.extractMin(), "from: extracts next");
182	        assertEqual(3, h.extractMin(), "from: extracts in sorted order");
183	
184	        Integer[] single = {42};
185	        MinHeap<Integer> h2 = MinHeap.from(single);
186	        assertEqual(42, h2.extractMin(), "from single-element array");
187	        assertTrue(h2.isEmpty(), "empty after extracting sole element");
188	
189	        MinHeap<Integer> h3 = MinHeap.from(arr, Comparator.reverseOrder());
190	        assertEqual(9, h3.extractMin(), "from with reverse comparator extracts maximum");
191	    }
192	
193	    private static void testWithStrings() {
194	        MinHeap<String> h = MinHeap.naturalOrder();
195	        h.insert("banana");
196	        h.insert("apple");
197	        h.insert("cherry");
198	        assertEqual("apple", h.extractMin(), "string heap extracts lexicographic minimum");
199	        assertEqual("banana", h.extractMin(), "string heap extracts next");
200	    }
201	
202	    private static void testMaxHeap() {
203	        MinHeap<Integer> h = MinHeap.reverseOrder();
204	        h.insert(5);
205	        h.insert(3);
206	        h.insert(8);
207	        h.insert(1);
208	        assertEqual(8, h.extractMin(), "max-heap: extracts largest first");
209	        assertEqual(5, h.extractMin(), "max-heap: extracts next largest");
210	    }
211	
212	    private static void testCustomComparator() {
213	        MinHeap<String> byLength = MinHeap.withComparator(Comparator.comparingInt(String::length));
214	        byLength.insert("banana");
215	        byLength.insert("fig");
216	        byLength.insert("kiwi");
217	        assertEqual("fig", byLength.extractMin(), "custom comparator: shortest string first");
218	        assertEqual("kiwi", byLength.extractMin(), "custom comparator: next shortest");
219	    }
